param([string]$MigrationPath = 'C:\Windows\Temp\002_native_auth.sql', [string]$ReportPath = 'C:\Windows\Temp\taxiassur-native-auth-migration.json')
$ErrorActionPreference='Stop'; $result=[ordered]@{ok=$false;users=0;initialized=0;error=$null}
function Read-Env($Path) { $v=@{}; Get-Content $Path | ForEach-Object { if ($_ -match '^\s*([^#][^=]+)=(.*)$') {$v[$matches[1].Trim()]=$matches[2].Trim().Trim('"').Trim("'")} }; $v }
try { $c=Read-Env 'F:\TaxiAssur\Secrets\postgresql.env'; $env:PGPASSWORD=$c.POSTGRES_PASSWORD; $p='F:\TaxiAssur\PostgreSQL\runtime\pgsql\bin\psql.exe'; & $p -X -q -v ON_ERROR_STOP=1 -h 127.0.0.1 -U postgres -d taxiassur -f $MigrationPath | Out-Null; $counts=(& $p -X -q -A -t -h 127.0.0.1 -U postgres -d taxiassur -c "SELECT json_build_object('users',count(*),'initialized',count(password_hash)) FROM taxiassur.auth_users;").Trim() | ConvertFrom-Json; $result.users=$counts.users; $result.initialized=$counts.initialized; $result.ok=$true } catch {$result.error=$_.Exception.Message}; $result | ConvertTo-Json | Set-Content $ReportPath -Encoding UTF8
